(ns exercises.lesson02.event-stream
  "Part 2: the event stream.
  The whole Datastar SSE writer, from the wire spec in sdk/ADR.md. Pure functions return
  strings; one-shot responses are plain Ring maps; a held-open stream uses http-kit's
  as-channel. Later lessons copy this namespace instead of using an SDK."
  (:require [cheshire.core :as json]
            [clojure.string :as string]
            [hiccup2.core :as h]
            [org.httpkit.server :as hk])
  (:import (java.net URI)
           (java.net.http HttpClient HttpRequest HttpResponse$BodyHandlers)
           (java.time LocalTime)
           (java.time.format DateTimeFormatter)))

(def datastar-cdn
  "https://cdn.jsdelivr.net/gh/starfederation/datastar@v1.0.4/bundles/datastar.js")

;; ---------------------------------------------------------------- the writer

