  )

(defn sse-response
  "A one-shot Ring response. The client reads the events until the body ends."
  [& events]
  {:status  200
   :headers {"Content-Type" "text/event-stream" "Cache-Control" "no-cache"}
   :body    (apply str events)})

(defn html-response
  "A text/html response. Datastar morphs each top-level element into the element with the same id."
  [html]
  {:status 200 :headers {"Content-Type" "text/html"} :body html})

;; ---------------------------------------------------------------- held open

(def stream-headers
  {"Content-Type" "text/event-stream" "Cache-Control" "no-cache" "Connection" "keep-alive"})

(defn- clock-html [n]
  (str (h/html [:div#clock (str "Tick " n " at "
                                (.format (LocalTime/now) (DateTimeFormatter/ofPattern "HH:mm:ss")))])))

(defonce closes (atom []))

(defn clock-handler
  "Hold the response open. Send one patch per tick, at most `ticks` times, then close.
  Stop early when the client goes away."
  [req tick-ms ticks]
  (hk/as-channel
   req
   {:on-open  (fn [ch]
                (hk/send! ch {:status 200 :headers stream-headers} false)
                (future
                  (loop [n 1]
                    (when (and (hk/open? ch) (<= n ticks))
                      (hk/send! ch (patch-elements (clock-html n) {}) false)
                      (Thread/sleep (long tick-ms))
                      (recur (inc n))))
                  (hk/close ch)))
    :on-close (fn [_ status] (swap! closes conj status))}))

;; ---------------------------------------------------------------- page + server

(defn page []
  (str "<!DOCTYPE html>"
       (h/html
        [:html
         [:head [:meta {:charset "utf-8"}] [:title "Part 2: the event stream"]
          [:script {:type "module" :src datastar-cdn}]]
         [:body
          [:h1 "The event stream"]
          [:ul#feed [:li "first item"]]
          [:div#clock "No clock yet."]
          [:p#status ""]
          [:button {:data-on:click "@get('/demo')"} "One response, four events"]
          " "
          [:button {:data-on:click "@get('/clock')"} "Open a clock stream"]]])))

(defn demo-response
  "Four events in one response: append, patch by id, set a signal, run a script."
  []
  (sse-response
   (patch-elements "<li>appended by the server</li>" {:selector "#feed" :mode :append})
   (patch-elements "<p id=\"status\">Patched by id.</p>" {})
   (patch-signals {:lastPatch "demo"} {})
   (execute-script "console.log('hello from the server')" {})))

(defn handler [{:keys [request-method uri] :as req}]
  (case [request-method uri]
    [:get "/"]      (html-response (page))
    [:get "/demo"]  (demo-response)
    [:get "/clock"] (clock-handler req 1000 10)
    {:status 404 :headers {"Content-Type" "text/plain"} :body "not found"}))

(defonce server (atom nil))

(defn stop! []
  (when-let [s @server]
    (hk/server-stop! s)
    (reset! server nil)))

(defn start!
  "Start the server. Port 0 lets the OS pick a free port. Return the port."
  [port]
  (stop!)
  (->> (hk/run-server #'handler {:port port :legacy-return-value? false})
       (reset! server)
       hk/server-port))

;; ---------------------------------------------------------------- demo

(defn- request [url]
  (-> (HttpRequest/newBuilder (URI. url))
      (.header "Datastar-Request" "true")
      (.header "Accept" "text/event-stream, text/html, application/json")
      .build))

(defn- read-events
  "Read a held-open stream line by line. Stop after n events, then shut the client down,
  which closes the TCP connection."
  [url n]
  (let [client (HttpClient/newHttpClient)
        t0     (System/currentTimeMillis)
        it     (-> (.send client (request url) (HttpResponse$BodyHandlers/ofLines)) .body .iterator)]
    (loop [events 0]
      (when (and (< events n) (.hasNext it))
        (let [line (.next it)]
          (println (format "  %5d ms │ %s" (- (System/currentTimeMillis) t0) line))
          (recur (cond-> events (string/blank? line) inc)))))
    (.shutdownNow client)))

(defn demo!
  "Run the narrated demo: start a server, make real requests, print what happens, stop."
  []
  (reset! closes [])
  (let [port (start! 0)
        url  (str "http://localhost:" port)]
    (println "Part 2: the event stream. Server on" url)
    (println "\n── Every event shape, as the wire sees it")
    (println "patch-elements, defaults left out:")
    (print (patch-elements "<div id=\"feed\">\n  <span>1</span>\n</div>" {}))
    (println "patch-elements, append into a selector, with an id and a retry:")
    (print (patch-elements "<li>new</li>" {:selector "#feed" :mode :append :id "e7" :retry 2000}))
    (println "remove-elements:")
    (print (remove-elements "#feed li:first-child" {}))
    (println "patch-signals (a null removes a signal):")
    (print (patch-signals {:count 3 :draft nil} {}))
    (println "execute-script (is really a patch-elements that appends a <script>):")
    (print (execute-script "alert('hi')" {}))
    (println "── GET /demo: one-shot response, four events, then the body ends")
    (print (.body (.send (HttpClient/newHttpClient) (request (str url "/demo"))
                         (HttpResponse$BodyHandlers/ofString))))
    (println "── GET /clock: held open. Times on the left are when each line arrived.")
    (read-events (str url "/clock") 3)
    (println "We closed the connection after 3 events. Did the server notice?")
    (loop [waited 0]
      (when (and (empty? @closes) (< waited 3000))
        (Thread/sleep 100)
        (recur (+ waited 100))))
    (println (if-let [status (first @closes)]
               (str "  on-close fired with status " status ". The server can stop work for this client.")
               "  on-close has not fired yet: this http-kit version did not notice the closed connection."))
    (println (str "\nTo try it in a browser: (exercises.lesson02.event-stream/start! 8080), then open http://localhost:8080/"))
    (stop!)))

(defn -main [& _]
  (demo!)
  (shutdown-agents))
